'<!doctype html>
<html><head><meta charset="utf-8"><style>
body { margin: 0; }
#ffgeom-grid { background: #fff; }
</style></head><body>
<script>
window.addEventListener("load", function () {
  var els = document.querySelectorAll("%s");
  var rows = [];
  for (var i = 0; i < els.length && i < 1000; ++i) {
    var e = els[i];
    var r = e.getBoundingClientRect();
    var cs = getComputedStyle(e);
    var v = [Math.round(r.top), Math.round(r.left),
             Math.round(r.width), Math.round(r.height),
             Math.round(parseFloat(cs.marginLeft)),
             Math.round(parseFloat(cs.marginRight)),
             Math.round(parseFloat(cs.paddingLeft)),
             Math.round(parseFloat(cs.paddingRight))];
    for (var k = 0; k < 8; ++k) if (v[k] < 0) v[k] += 65536;
    rows.push(v);
  }
  var cv = document.createElement("canvas");
  cv.id = "ffgeom-grid";
  // Pinned to the viewport's top-left whatever the page does to <body>
  // (flex/grid, padding, transforms): decode() reads the grid at (0,0).
  cv.style.cssText = "position:fixed;left:0;top:0;z-index:2147483647;" +
                     "margin:0;border:0;padding:0;transform:none;display:block";
  var rowsN = rows.length * 8 + 3;
  cv.width = 64;
  cv.height = rowsN * 4;
  document.body.replaceChildren(cv);
  var ctx = cv.getContext("2d");
  ctx.fillStyle = "#fff";
  ctx.fillRect(0, 0, cv.width, cv.height);
  ctx.fillStyle = "#000";
  function cell(r, c) { ctx.fillRect(c * 4, r * 4, 4, 4); }
  function word(row, v) {
    for (var b = 0; b < 16; ++b)
      if ((v >> (15 - b)) & 1) cell(row, b);
  }
  word(0, 0xFFFF);
  word(1, 0xC0DE);
  word(2, rowsN);
  var rw = 3;
  for (var i = 0; i < rows.length; ++i)
    for (var v = 0; v < 8; ++v) word(rw++, rows[i][v]);
});
</script></body></html>
